// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// DeleteSpriteCandidate Remove a candidate
	// (DELETE /candidates/{candidateId})
	DeleteSpriteCandidate(ctx context.Context, request DeleteSpriteCandidateRequestObject) (DeleteSpriteCandidateResponseObject, error)
	// GetSpriteCandidate One candidate with its SVG and house-style warnings
	// (GET /candidates/{candidateId})
	GetSpriteCandidate(ctx context.Context, request GetSpriteCandidateRequestObject) (GetSpriteCandidateResponseObject, error)
	// AcceptSpriteCandidate Make a candidate its form's sprite
	// (POST /candidates/{candidateId}/accept)
	AcceptSpriteCandidate(ctx context.Context, request AcceptSpriteCandidateRequestObject) (AcceptSpriteCandidateResponseObject, error)
	// ExportCatalog The catalog as a game build would load it
	// (GET /export)
	ExportCatalog(ctx context.Context, request ExportCatalogRequestObject) (ExportCatalogResponseObject, error)
	// PreviewSpecies Roll species without saving them
	// (GET /preview)
	PreviewSpecies(ctx context.Context, request PreviewSpeciesRequestObject) (PreviewSpeciesResponseObject, error)
	// ListSpecies List saved species, newest first
	// (GET /species)
	ListSpecies(ctx context.Context, request ListSpeciesRequestObject) (ListSpeciesResponseObject, error)
	// CreateSpecies Roll and save a species
	// (POST /species)
	CreateSpecies(ctx context.Context, request CreateSpeciesRequestObject) (CreateSpeciesResponseObject, error)
	// DeleteSpecies Remove a species and its sprites
	// (DELETE /species/{speciesId})
	DeleteSpecies(ctx context.Context, request DeleteSpeciesRequestObject) (DeleteSpeciesResponseObject, error)
	// GetSpecies One species with its sprite slots
	// (GET /species/{speciesId})
	GetSpecies(ctx context.Context, request GetSpeciesRequestObject) (GetSpeciesResponseObject, error)
	// UpdateSpecies Replace a species' notes or field notes
	// (PATCH /species/{speciesId})
	UpdateSpecies(ctx context.Context, request UpdateSpeciesRequestObject) (UpdateSpeciesResponseObject, error)
	// ListSpriteCandidates A species' sprite candidates, newest first within each form
	// (GET /species/{speciesId}/candidates)
	ListSpriteCandidates(ctx context.Context, request ListSpriteCandidatesRequestObject) (ListSpriteCandidatesResponseObject, error)
	// GetSpriteBrief The drawing brief for one form
	// (GET /species/{speciesId}/forms/{form}/brief)
	GetSpriteBrief(ctx context.Context, request GetSpriteBriefRequestObject) (GetSpriteBriefResponseObject, error)
	// SubmitSpriteCandidate Store an SVG as a candidate sprite for one form
	// (POST /species/{speciesId}/forms/{form}/candidates)
	SubmitSpriteCandidate(ctx context.Context, request SubmitSpriteCandidateRequestObject) (SubmitSpriteCandidateResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

